function requiresAuth(pathname) {
  const publicPaths = [
    "/",
    // 主页（会显示登录界面）
    "/api/login",
    // 登录接口
    "/api/logout",
    // 退出登录接口
    "/api/refresh-token",
    // Token 刷新接口（已在内部验证）
    "/api/setup",
    // 首次设置接口
    "/api/time",
    // 客户端 TOTP 时间校准接口
    "/setup",
    // 设置页面
    "/manifest.json",
    // PWA manifest
    "/sw.js",
    // Service Worker
    "/icon-192.png",
    // PWA 图标
    "/icon-512.png",
    // PWA 图标
    "/favicon.ico",
    // 网站图标
    "/otp",
    // OTP 生成页面（无参数）
    "/api/onedrive/oauth/callback",
    "/api/gdrive/oauth/callback"
  ];
  if (publicPaths.includes(pathname)) {
    return false;
  }
  if (pathname.startsWith("/otp/")) {
    return false;
  }
  if (pathname.startsWith("/api/favicon/")) {
    return false;
  }
  return true;
}
