    // \u6267\u884C\u5BFC\u5165
    // \u7531\u6784\u5EFA\u671F\u4ECE LIMITS.BULK_IMPORT_CHUNK_SIZE \u6CE8\u5165\uFF0C\u4E0E\u540E\u7AEF batch.js/validation.js \u4FDD\u6301\u4E00\u81F4
