        title: '\u6279\u91CF\u5BFC\u5165\u4E2D',
        message: totalChunks > 1 ? ('\u51C6\u5907\u5BFC\u5165\u7B2C 1 / ' + totalChunks + ' \u6279...') : '\u51C6\u5907\u5BFC\u5165...',
        totalItems: originalTotalItems,
