// src/ui/scripts/tools/base32Tool.js
function getBase32ToolCode() {
  return `
    // ==================== Base32\u7F16\u89E3\u7801\u5DE5\u5177 ====================

    function showBase32Modal() {
      showModal('base32Modal', () => {
        document.getElementById('plainTextInput').value = '';
        document.getElementById('base32TextInput').value = '';
        document.getElementById('encodedResult').textContent = '';
        document.getElementById('decodedResult').textContent = '';
      });
    }

    function hideBase32Modal() {
      hideModal('base32Modal');
    }

    // Base32\u5B57\u7B26\u96C6
    const base32Chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';

    // UTF-8\u7F16\u7801\u51FD\u6570
    function utf8Encode(str) {
      const bytes = [];
      for (let i = 0; i < str.length; i++) {
        const code = str.charCodeAt(i);
        if (code < 0x80) {
          bytes.push(code);
        } else if (code < 0x800) {
          bytes.push(0xc0 | (code >> 6));
          bytes.push(0x80 | (code & 0x3f));
        } else if (code < 0xd800 || code >= 0xe000) {
          bytes.push(0xe0 | (code >> 12));
          bytes.push(0x80 | ((code >> 6) & 0x3f));
          bytes.push(0x80 | (code & 0x3f));
        } else {
          // \u5904\u7406UTF-16\u4EE3\u7406\u5BF9
          i++;
          const c2 = str.charCodeAt(i);
          const cp = 0x10000 + ((code & 0x3ff) << 10) + (c2 & 0x3ff);
          bytes.push(0xf0 | (cp >> 18));
          bytes.push(0x80 | ((cp >> 12) & 0x3f));
          bytes.push(0x80 | ((cp >> 6) & 0x3f));
          bytes.push(0x80 | (cp & 0x3f));
        }
      }
      return bytes;
    }

    // UTF-8\u89E3\u7801\u51FD\u6570
    function utf8Decode(bytes) {
      let str = '';
      for (let i = 0; i < bytes.length;) {
        const b1 = bytes[i++];
        if (b1 < 0x80) {
          str += String.fromCharCode(b1);
        } else if (b1 < 0xe0) {
          const b2 = bytes[i++];
          str += String.fromCharCode(((b1 & 0x1f) << 6) | (b2 & 0x3f));
        } else if (b1 < 0xf0) {
          const b2 = bytes[i++];
          const b3 = bytes[i++];
          str += String.fromCharCode(((b1 & 0x0f) << 12) | ((b2 & 0x3f) << 6) | (b3 & 0x3f));
        } else {
          const b2 = bytes[i++];
          const b3 = bytes[i++];
          const b4 = bytes[i++];
          const cp = ((b1 & 0x07) << 18) | ((b2 & 0x3f) << 12) | ((b3 & 0x3f) << 6) | (b4 & 0x3f);
          if (cp > 0xffff) {
            const ch = cp - 0x10000;
            str += String.fromCharCode(0xd800 + (ch >> 10));
            str += String.fromCharCode(0xdc00 + (ch & 0x3ff));
          } else {
            str += String.fromCharCode(cp);
          }
        }
      }
      return str;
    }

    function encodeBase32() {
      const text = document.getElementById('plainTextInput').value.trim();
      if (!text) {
        showCenterToast('\u274C', '\u8BF7\u8F93\u5165\u8981\u7F16\u7801\u7684\u6587\u672C');
        return;
      }

      try {
        // \u5148\u5C06\u6587\u672C\u8F6C\u6362\u4E3AUTF-8\u5B57\u8282\u6570\u7EC4
        const bytes = utf8Encode(text);
        let bits = 0;
        let bitsLength = 0;
        let result = '';

        // \u5904\u7406\u6BCF\u4E2A\u5B57\u8282
        for (let i = 0; i < bytes.length; i++) {
          bits = (bits << 8) | bytes[i];
          bitsLength += 8;

          // \u6BCF5\u4F4D\u751F\u6210\u4E00\u4E2ABase32\u5B57\u7B26
          while (bitsLength >= 5) {
            bitsLength -= 5;
            result += base32Chars[(bits >>> bitsLength) & 31];
          }
        }

        // \u5904\u7406\u5269\u4F59\u7684\u4F4D
        if (bitsLength > 0) {
          bits = bits << (5 - bitsLength);
          result += base32Chars[bits & 31];
        }

        // \u6DFB\u52A0\u586B\u5145
        while (result.length % 8 !== 0) {
          result += '=';
        }

        const resultElement = document.getElementById('encodedResult');
        resultElement.textContent = result;
        resultElement.style.display = 'block';
        showCenterToast('\u2705', 'Base32\u7F16\u7801\u6210\u529F');
      } catch (error) {
        showCenterToast('\u274C', '\u7F16\u7801\u5931\u8D25\uFF1A' + error.message);
      }
    }

    function decodeBase32() {
      const base32Text = document.getElementById('base32TextInput').value.trim().toUpperCase();
      if (!base32Text) {
        showCenterToast('\u274C', '\u8BF7\u8F93\u5165\u8981\u89E3\u7801\u7684Base32\u6587\u672C');
        return;
      }

      try {
        // \u79FB\u9664\u586B\u5145
        const cleaned = base32Text.replace(/=/g, '');

        // \u9A8C\u8BC1\u5B57\u7B26\u96C6
        if (!/^[A-Z2-7]+$/.test(cleaned)) {
          throw new Error('\u5305\u542B\u65E0\u6548\u7684Base32\u5B57\u7B26');
        }

        let bits = 0;
        let bitsLength = 0;
        let bytes = [];

        // \u5904\u7406\u6BCF\u4E2ABase32\u5B57\u7B26
        for (let i = 0; i < cleaned.length; i++) {
          const char = cleaned[i];
          const value = base32Chars.indexOf(char);

          if (value === -1) {
            throw new Error('\u65E0\u6548\u7684Base32\u5B57\u7B26\uFF1A' + char);
          }

          bits = (bits << 5) | value;
          bitsLength += 5;

          // \u6BCF8\u4F4D\u751F\u6210\u4E00\u4E2A\u5B57\u8282
          while (bitsLength >= 8) {
            bitsLength -= 8;
            bytes.push((bits >>> bitsLength) & 255);
          }
        }

        // \u89E3\u7801UTF-8\u5B57\u8282\u6570\u7EC4
        const result = utf8Decode(bytes);
        const resultElement = document.getElementById('decodedResult');
        resultElement.textContent = result;
        resultElement.style.display = 'block';
        showCenterToast('\u2705', 'Base32\u89E3\u7801\u6210\u529F');
      } catch (error) {
        showCenterToast('\u274C', '\u89E3\u7801\u5931\u8D25\uFF1A' + error.message);
      }
    }

    async function copyEncodedText() {
      const text = document.getElementById('encodedResult').textContent;
      if (!text) {
        showCenterToast('\u274C', '\u6CA1\u6709\u53EF\u590D\u5236\u7684\u5185\u5BB9');
        return;
      }

      try {
        await navigator.clipboard.writeText(text);
        showCenterToast('\u2705', '\u5DF2\u590D\u5236\u7F16\u7801\u7ED3\u679C');
      } catch (error) {
        showCenterToast('\u274C', '\u590D\u5236\u5931\u8D25');
      }
    }

    async function copyDecodedText() {
      const text = document.getElementById('decodedResult').textContent;
      if (!text) {
        showCenterToast('\u274C', '\u6CA1\u6709\u53EF\u590D\u5236\u7684\u5185\u5BB9');
        return;
      }

      try {
        await navigator.clipboard.writeText(text);
        showCenterToast('\u2705', '\u5DF2\u590D\u5236\u89E3\u7801\u7ED3\u679C');
      } catch (error) {
        showCenterToast('\u274C', '\u590D\u5236\u5931\u8D25');
      }
    }


`;
}
__name(getBase32ToolCode, "getBase32ToolCode");

// src/ui/scripts/tools/timestampTool.js
function getTimestampToolCode() {
  return `
    // ==================== \u65F6\u95F4\u6233\u5DE5\u5177 ====================

    let currentPeriod = 30;
    let timestampInterval = null;

    function showTimestampModal() {
      showModal('timestampModal', () => {
        // \u8BBE\u7F6E\u9ED8\u8BA4\u5468\u671F
        setPeriod(30);

        // \u5F00\u59CB\u66F4\u65B0
        updateTimestamp();
        timestampInterval = setInterval(updateTimestamp, 1000);
      });
    }

    function hideTimestampModal() {
      hideModal('timestampModal', () => {
        if (timestampInterval) {
          clearInterval(timestampInterval);
          timestampInterval = null;
        }
      });
    }

    function setPeriod(period) {
      currentPeriod = period;

      // \u66F4\u65B0\u6309\u94AE\u72B6\u6001 - \u4F7F\u7528CSS\u7C7B\u800C\u4E0D\u662F\u5185\u8054\u6837\u5F0F
      const buttons = ['period30Btn', 'period60Btn', 'period120Btn'];
      const periods = [30, 60, 120];

      buttons.forEach((btnId, index) => {
        const btn = document.getElementById(btnId);
        if (period === periods[index]) {
          btn.classList.add('active');
        } else {
          btn.classList.remove('active');
        }
      });

      updateTimestamp();
    }

    function updateTimestamp() {
      const now = Math.floor(Date.now() / 1000);
      const counter = Math.floor(now / currentPeriod);
      const remaining = currentPeriod - (now % currentPeriod);
      const progress = (remaining / currentPeriod) * 100;

      document.getElementById('currentTimestamp').textContent = now;
      document.getElementById('totpPeriod').textContent = currentPeriod + ' \u79D2';
      document.getElementById('totpCounter').textContent = counter;
      document.getElementById('remainingTime').textContent = remaining + ' \u79D2';

      const progressBar = document.getElementById('progressBar');
      progressBar.style.width = progress + '%';

      // \u4F7F\u7528\u4E0E\u4E3B\u754C\u9762\u5361\u7247\u4E00\u81F4\u7684\u6E10\u53D8\u914D\u8272\uFF08\u7EFF\u8272\u5230\u84DD\u8272\uFF09
      // \u4F7F\u7528 CSS \u53D8\u91CF\u786E\u4FDD\u4E3B\u9898\u4E00\u81F4\u6027
      const style = getComputedStyle(document.documentElement);
      const progressFill = style.getPropertyValue('--progress-fill').trim() || 'linear-gradient(90deg, #4CAF50, #2196F3)';
      progressBar.style.background = progressFill;
    }

`;
}
__name(getTimestampToolCode, "getTimestampToolCode");

// src/ui/scripts/tools/keyChecker.js
function getKeyCheckerToolCode() {
  return `
    // ==================== \u5BC6\u94A5\u68C0\u67E5\u5668 ====================

    function showKeyCheckModal() {
      showModal('keyCheckModal', () => {
        document.getElementById('keyCheckInput').value = '';
        document.getElementById('keyCheckResult').style.display = 'none';
      });
    }

    function hideKeyCheckModal() {
      hideModal('keyCheckModal');
    }

    function checkSecret() {
      const secret = document.getElementById('keyCheckInput').value.trim().toUpperCase();
      if (!secret) {
        showCenterToast('\u274C', '\u8BF7\u8F93\u5165\u8981\u68C0\u67E5\u7684\u5BC6\u94A5');
        return;
      }

      const result = validateSecretFormat(secret);
      displayCheckResult(result);
    }

    function validateSecretFormat(secret) {
      const result = {
        isValid: false,
        length: secret.length,
        lengthValid: false,
        charsetValid: false,
        paddingValid: false,
        suggestions: []
      };

      // \u68C0\u67E5\u957F\u5EA6
      result.lengthValid = secret.length >= 8;
      if (!result.lengthValid) {
        result.suggestions.push('\u5BC6\u94A5\u957F\u5EA6\u81F3\u5C11\u9700\u89818\u4E2A\u5B57\u7B26');
      }

      // \u68C0\u67E5\u5B57\u7B26\u96C6
      const base32Regex = /^[A-Z2-7]+=*$/;
      result.charsetValid = base32Regex.test(secret);
      if (!result.charsetValid) {
        result.suggestions.push('\u53EA\u80FD\u5305\u542BA-Z\u548C2-7\u7684\u5B57\u7B26');
      }

      // \u68C0\u67E5\u586B\u5145
      const withoutPadding = secret.replace(/=+$/, '');
      const paddingLength = secret.length - withoutPadding.length;
      result.paddingValid = paddingLength === 0 || paddingLength <= 6;
      if (!result.paddingValid) {
        result.suggestions.push('\u586B\u5145\u5B57\u7B26(=)\u4E0D\u80FD\u8D85\u8FC76\u4E2A');
      }

      // \u68C0\u67E5\u957F\u5EA6\u662F\u5426\u4E3A8\u7684\u500D\u6570\uFF08\u8003\u8651\u586B\u5145\uFF09
      const totalLength = withoutPadding.length + paddingLength;
      if (totalLength % 8 !== 0) {
        result.suggestions.push('\u586B\u5145\u540E\u7684\u603B\u957F\u5EA6\u5FC5\u987B\u662F8\u7684\u500D\u6570');
      }

      // \u6574\u4F53\u6709\u6548\u6027
      result.isValid = result.lengthValid && result.charsetValid && result.paddingValid;

      return result;
    }

    function displayCheckResult(result) {
      const resultDiv = document.getElementById('checkResultContent');
      const resultSection = document.getElementById('keyCheckResult');

      let html = '<div style="display: flex; align-items: center; margin-bottom: 15px;">' +
        '<span style="font-size: 24px; margin-right: 10px;">' + (result.isValid ? '\u2705' : '\u274C') + '</span>' +
        '<span style="font-size: 18px; font-weight: 600; color: ' + (result.isValid ? '#28a745' : '#e74c3c') + ';">' + (result.isValid ? '\u5BC6\u94A5\u6709\u6548' : '\u5BC6\u94A5\u65E0\u6548') + '</span>' +
        '</div>' +
        '<div style="margin-bottom: 15px;">' +
        '<div style="display: flex; justify-content: space-between; margin-bottom: 8px;">' +
        '<span style="font-weight: 600;">\u957F\u5EA6:</span>' +
        '<span style="color: ' + (result.lengthValid ? '#28a745' : '#e74c3c') + ';">' + result.length + ' \u5B57\u7B26 ' + (result.lengthValid ? '(\u7B26\u5408\u8981\u6C42)' : '(\u4E0D\u7B26\u5408\u8981\u6C42)') + '</span>' +
        '</div>' +
        '<div style="display: flex; justify-content: space-between; margin-bottom: 8px;">' +
        '<span style="font-weight: 600;">\u5B57\u7B26\u96C6:</span>' +
        '<span style="color: ' + (result.charsetValid ? '#28a745' : '#e74c3c') + ';">' + (result.charsetValid ? '\u7B26\u5408Base32\u89C4\u8303' : '\u5305\u542B\u975E\u6CD5\u5B57\u7B26') + '</span>' +
        '</div>' +
        '<div style="display: flex; justify-content: space-between;">' +
        '<span style="font-weight: 600;">\u586B\u5145:</span>' +
        '<span style="color: ' + (result.paddingValid ? '#28a745' : '#e74c3c') + ';">' + (result.paddingValid ? '\u586B\u5145\u6B63\u786E' : '\u586B\u5145\u9519\u8BEF') + '</span>' +
        '</div>' +
        '</div>';

      if (!result.isValid && result.suggestions.length > 0) {
        html += '<div style="margin-top: 15px; padding: 10px; background: #fff3cd; border-radius: 6px;">' +
          '<div style="font-weight: 600; margin-bottom: 8px; color: #856404;">\u6539\u8FDB\u5EFA\u8BAE:</div>' +
          '<div style="font-size: 13px; color: #856404;">' +
          result.suggestions.map(suggestion => '\u2022 ' + suggestion).join('<br>') +
          '</div>' +
          '</div>';
      }

      resultDiv.innerHTML = html;
      resultSection.style.display = 'block';
    }


`;
}
__name(getKeyCheckerToolCode, "getKeyCheckerToolCode");

// src/ui/scripts/tools/keyGenerator.js
function getKeyGeneratorToolCode() {
  return `
    // ==================== \u5BC6\u94A5\u751F\u6210\u5668 ====================

    let currentKeyLength = 16;

    function showKeyGeneratorModal() {
      showModal('keyGeneratorModal', () => {
        // \u8BBE\u7F6E\u9ED8\u8BA4\u957F\u5EA6
        setKeyLength(16);

        // \u9690\u85CF\u7ED3\u679C\u533A\u57DF
        document.getElementById('keyResultSection').style.display = 'none';
      });
    }

    function hideKeyGeneratorModal() {
      hideModal('keyGeneratorModal');
    }

    function setKeyLength(length) {
      currentKeyLength = length;

      // \u66F4\u65B0\u6309\u94AE\u72B6\u6001 - \u4F7F\u7528CSS\u7C7B\u800C\u4E0D\u662F\u5185\u8054\u6837\u5F0F
      const buttons = ['length16Btn', 'length26Btn', 'length32Btn'];
      const lengths = [16, 26, 32];

      buttons.forEach((btnId, index) => {
        const btn = document.getElementById(btnId);
        if (length === lengths[index]) {
          btn.classList.add('active');
        } else {
          btn.classList.remove('active');
        }
      });
    }

    function generateKey() {
      const key = generateRandomBase32Key(currentKeyLength);
      document.getElementById('generatedKeyText').textContent = key;
      document.getElementById('keyResultSection').style.display = 'block';
      showCenterToast('\u2705', '\u5BC6\u94A5\u751F\u6210\u6210\u529F');
    }

    function generateRandomBase32Key(length) {
      const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
      let result = '';
      for (let i = 0; i < length; i++) {
        result += chars.charAt(Math.floor(Math.random() * chars.length));
      }
      return result;
    }

    async function copyGeneratedKey() {
      const key = document.getElementById('generatedKeyText').textContent;
      if (!key) {
        showCenterToast('\u274C', '\u6CA1\u6709\u53EF\u590D\u5236\u7684\u5BC6\u94A5');
        return;
      }

      try {
        await navigator.clipboard.writeText(key);
        showCenterToast('\u2705', '\u5BC6\u94A5\u5DF2\u590D\u5236\u5230\u526A\u8D34\u677F');
      } catch (error) {
        showCenterToast('\u274C', '\u590D\u5236\u5931\u8D25');
      }
    }

`;
}
__name(getKeyGeneratorToolCode, "getKeyGeneratorToolCode");

// src/ui/scripts/tools/webdavTool.js
function getWebdavToolCode() {
  return `
    // ==================== WebDAV \u540C\u6B65\u5DE5\u5177\uFF08\u591A\u76EE\u6807\uFF09 ====================

    let _webdavOnClose = null;

    function showWebdavModal(onClose) {
      _webdavOnClose = typeof onClose === 'function' ? onClose : null;
      showModal('webdavModal', () => {
        loadWebdavDestinations();
      });
    }

    function hideWebdavModal() {
      const onClose = _webdavOnClose;
      _webdavOnClose = null;
      hideModal('webdavModal', onClose);
    }

    async function loadWebdavDestinations() {
      const listEl = document.getElementById('webdavDestinationList');
      const addBtn = document.getElementById('webdavAddBtn');

      try {
        const response = await authenticatedFetch('/api/webdav/config');
        const data = await response.json();

        // \u6E32\u67D3\u76EE\u6807\u5217\u8868
        if (data.destinations && data.destinations.length > 0) {
          listEl.innerHTML = data.destinations.map(dest => _renderWebdavCard(dest)).join('');
        } else {
          listEl.innerHTML = '<div style="text-align: center; padding: 20px; color: var(--text-tertiary); font-size: 13px;">\u6682\u65E0 WebDAV \u76EE\u6807\uFF0C\u70B9\u51FB\u4E0B\u65B9\u6309\u94AE\u6DFB\u52A0</div>';
        }

        // \u8FBE\u5230\u4E0A\u9650\u65F6\u9690\u85CF\u6DFB\u52A0\u6309\u94AE
        addBtn.style.display = data.count >= data.maxAllowed ? 'none' : 'block';

        // \u9690\u85CF\u8868\u5355
        hideWebdavForm();
      } catch (error) {
        console.error('\u52A0\u8F7D WebDAV \u914D\u7F6E\u5931\u8D25:', error);
        listEl.innerHTML = '<div style="text-align: center; padding: 20px; color: var(--danger-color); font-size: 13px;">\u52A0\u8F7D\u5931\u8D25\uFF0C\u8BF7\u7A0D\u540E\u91CD\u8BD5</div>';
      }
    }

    function _renderWebdavCard(dest) {
      let statusDot = 'dest-status-dot-gray';
      let statusText = '\u672A\u63A8\u9001';

      if (dest.status.lastError) {
        statusDot = 'dest-status-dot-red';
        statusText = '\u5931\u8D25: ' + dest.status.lastError.error;
      } else if (dest.status.lastSuccess) {
        statusDot = 'dest-status-dot-green';
        statusText = new Date(dest.status.lastSuccess.timestamp).toLocaleString();
      }

      const enabledClass = dest.enabled ? '' : 'dest-card-disabled';

      return '<div class="dest-card ' + enabledClass + '" data-id="' + dest.id + '">'
        + '<div class="dest-card-header">'
        + '<div class="dest-card-info">'
        + '<span class="dest-card-name">' + _escapeHtml(dest.name) + '</span>'
        + '<span class="dest-card-url">' + _escapeHtml(dest.config.url) + '</span>'
        + '</div>'
        + '<label class="dest-toggle" onclick="event.stopPropagation()">'
        + '<input type="checkbox" ' + (dest.enabled ? 'checked' : '') + ' onchange="toggleWebdavDest(\\'' + dest.id + '\\', this.checked)" />'
        + '<span class="dest-toggle-slider"></span>'
        + '</label>'
        + '</div>'
        + '<div class="dest-card-status">'
        + '<span class="dest-status-dot ' + statusDot + '"></span>'
        + '<span class="dest-status-text">' + _escapeHtml(statusText) + '</span>'
        + '</div>'
        + '<div class="dest-card-actions">'
        + '<button class="btn btn-sm" onclick="event.stopPropagation(); editWebdavDest(\\'' + dest.id + '\\')" style="font-size: 12px; padding: 4px 12px;">\u7F16\u8F91</button>'
        + '<button class="btn btn-sm btn-danger-outline" onclick="event.stopPropagation(); deleteWebdavDest(\\'' + dest.id + '\\', \\'' + _escapeHtml(dest.name).replace(/'/g, "\\\\'") + '\\')" style="font-size: 12px; padding: 4px 12px;">\u5220\u9664</button>'
        + '</div>'
        + '</div>';
    }

    function _escapeHtml(str) {
      const div = document.createElement('div');
      div.textContent = str;
      return div.innerHTML;
    }

    function showWebdavForm(id) {
      const formArea = document.getElementById('webdavFormArea');
      const addBtn = document.getElementById('webdavAddBtn');
      formArea.style.display = 'block';
      addBtn.style.display = 'none';

      if (!id) {
        // \u65B0\u589E\u6A21\u5F0F\uFF1A\u6E05\u7A7A\u8868\u5355
        document.getElementById('webdavEditId').value = '';
        document.getElementById('webdavName').value = '';
        document.getElementById('webdavUrl').value = '';
        document.getElementById('webdavUsername').value = '';
        document.getElementById('webdavPassword').value = '';
        document.getElementById('webdavPassword').placeholder = '\u8BF7\u8F93\u5165\u5BC6\u7801';
        document.getElementById('webdavPath').value = '/';
      }
    }

    function hideWebdavForm() {
      document.getElementById('webdavFormArea').style.display = 'none';
    }

    async function editWebdavDest(id) {
      try {
        const response = await authenticatedFetch('/api/webdav/config');
        const data = await response.json();
        const dest = data.destinations.find(d => d.id === id);
        if (!dest) return;

        document.getElementById('webdavEditId').value = dest.id;
        document.getElementById('webdavName').value = dest.name;
        document.getElementById('webdavUrl').value = dest.config.url;
        document.getElementById('webdavUsername').value = dest.config.username;
        document.getElementById('webdavPassword').value = '';
        document.getElementById('webdavPassword').placeholder = dest.config.hasPassword ? '\u5DF2\u4FDD\u5B58\uFF08\u7559\u7A7A\u4FDD\u6301\u4E0D\u53D8\uFF09' : '\u8BF7\u8F93\u5165\u5BC6\u7801';
        document.getElementById('webdavPath').value = dest.config.path || '/';

        showWebdavForm(id);
      } catch (error) {
        showCenterToast('\u274C', '\u52A0\u8F7D\u914D\u7F6E\u5931\u8D25: ' + error.message);
      }
    }

    async function saveWebdavConfig() {
      const id = document.getElementById('webdavEditId').value;
      const name = document.getElementById('webdavName').value.trim();
      const url = document.getElementById('webdavUrl').value.trim();
      const username = document.getElementById('webdavUsername').value.trim();
      const password = document.getElementById('webdavPassword').value;
      const path = document.getElementById('webdavPath').value.trim() || '/';

      if (!name || !url || !username) {
        showCenterToast('\u26A0\uFE0F', '\u8BF7\u586B\u5199\u76EE\u6807\u540D\u79F0\u3001\u670D\u52A1\u5668\u5730\u5740\u548C\u7528\u6237\u540D');
        return;
      }

      const saveBtn = document.getElementById('webdavSaveBtn');
      const originalText = saveBtn.textContent;
      saveBtn.textContent = '\u4FDD\u5B58\u4E2D...';
      saveBtn.disabled = true;

      try {
        const body = { name, url, username, password, path };
        if (id) body.id = id;

        const response = await authenticatedFetch('/api/webdav/config', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(body)
        });
        const data = await response.json();

        if (data.success) {
          if (data.warning) {
            showCenterToast('\u26A0\uFE0F', data.warning);
          } else {
            showCenterToast('\u2705', 'WebDAV \u914D\u7F6E\u5DF2\u4FDD\u5B58');
          }
          loadWebdavDestinations();
        } else {
          showCenterToast('\u274C', data.message || '\u4FDD\u5B58\u5931\u8D25');
        }
      } catch (error) {
        showCenterToast('\u274C', '\u4FDD\u5B58\u5931\u8D25: ' + error.message);
      } finally {
        saveBtn.textContent = originalText;
        saveBtn.disabled = false;
      }
    }

    async function testWebdavConnection() {
      const id = document.getElementById('webdavEditId').value;
      const name = document.getElementById('webdavName').value.trim();
      const url = document.getElementById('webdavUrl').value.trim();
      const username = document.getElementById('webdavUsername').value.trim();
      const password = document.getElementById('webdavPassword').value;
      const path = document.getElementById('webdavPath').value.trim() || '/';

      if (!name || !url || !username) {
        showCenterToast('\u26A0\uFE0F', '\u8BF7\u586B\u5199\u76EE\u6807\u540D\u79F0\u3001\u670D\u52A1\u5668\u5730\u5740\u548C\u7528\u6237\u540D');
        return;
      }

      const testBtn = document.getElementById('webdavTestBtn');
      const originalText = testBtn.textContent;
      testBtn.textContent = '\u6D4B\u8BD5\u4E2D...';
      testBtn.disabled = true;

      try {
        const body = { name, url, username, password, path };
        if (id) body.id = id;

        const response = await authenticatedFetch('/api/webdav/test', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(body)
        });
        const data = await response.json();

        if (data.success) {
          showCenterToast('\u2705', data.message || '\u8FDE\u63A5\u6210\u529F');
        } else {
          showCenterToast('\u274C', data.message || '\u8FDE\u63A5\u5931\u8D25');
        }
      } catch (error) {
        showCenterToast('\u274C', '\u6D4B\u8BD5\u5931\u8D25: ' + error.message);
      } finally {
        testBtn.textContent = originalText;
        testBtn.disabled = false;
      }
    }

    async function deleteWebdavDest(id, name) {
      const confirmed = await showConfirmDialog({
        title: '\u5220\u9664 WebDAV \u76EE\u6807',
        message: '\u786E\u5B9A\u8981\u5220\u9664 WebDAV \u76EE\u6807\u300C' + name + '\u300D\u5417\uFF1F\\n\u5220\u9664\u540E\u8BE5\u76EE\u6807\u5C06\u4E0D\u518D\u63A5\u6536\u5907\u4EFD\u63A8\u9001\u3002',
        confirmText: '\u5220\u9664',
        cancelText: '\u53D6\u6D88',
        danger: true
      });
      if (!confirmed) {
        return;
      }

      try {
        const response = await authenticatedFetch('/api/webdav/config?id=' + encodeURIComponent(id), {
          method: 'DELETE'
        });
        const data = await response.json();

        if (data.success) {
          showCenterToast('\u2705', 'WebDAV \u76EE\u6807\u5DF2\u5220\u9664');
          loadWebdavDestinations();
        } else {
          showCenterToast('\u274C', data.message || '\u5220\u9664\u5931\u8D25');
        }
      } catch (error) {
        showCenterToast('\u274C', '\u5220\u9664\u5931\u8D25: ' + error.message);
      }
    }

    async function toggleWebdavDest(id, enabled) {
      try {
        const response = await authenticatedFetch('/api/webdav/toggle', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id, enabled })
        });
        const data = await response.json();

        if (data.success) {
          showCenterToast('\u2705', data.message);
          loadWebdavDestinations();
        } else {
          showCenterToast('\u274C', data.message || '\u64CD\u4F5C\u5931\u8D25');
          loadWebdavDestinations();
        }
      } catch (error) {
        showCenterToast('\u274C', '\u64CD\u4F5C\u5931\u8D25: ' + error.message);
        loadWebdavDestinations();
      }
    }

`;
}
__name(getWebdavToolCode, "getWebdavToolCode");

