            warningEl.textContent = '\u670D\u52A1\u7AEF\u672A\u914D\u7F6E Google Drive OAuth \u51ED\u636E\u3002\u5F53\u524D\u4ECD\u53EF\u65B0\u589E\u3001\u67E5\u770B\u548C\u7F16\u8F91\u76EE\u6807\uFF0C\u4F46\u6682\u65F6\u65E0\u6CD5\u5B8C\u6210\u6388\u6743\u6216\u542F\u7528\u540C\u6B65\u3002';
