      const localDefaultFormat = localStorage.getItem('defaultExportFormat') || 'json';
      if (formatSelect) {
        formatSelect.value = localDefaultFormat;
      }

      // \u5BFC\u51FA\u504F\u597D\u683C\u5F0F\u3001\u767B\u5F55\u6709\u6548\u671F\u548C\u5907\u4EFD\u4FDD\u7559\u6570\u91CF\uFF08\u4ECE\u670D\u52A1\u5668\u8BFB\u53D6\uFF09
